import type { PageId } from './leitura';

/**
 * V20/V21 · ficha de cada bloco e cartão do painel, lida pelo (i). Chave: `${aba}.${id do bloco}`.
 * Campos: o que mede, como calcula, fontes e data, cruzamento (quando houver), regra e versão, limitações, dono e, só onde faz
 * sentido, uma ação sugerida. "Último cálculo" é preenchido na tela com a data de referência. Um teste garante que todo bloco e
 * todo cartão com ficha declarada tem a sua entrada aqui.
 */
export interface FichaBloco { mede: string; calcula: string; fontes: string; cruzamento?: string; regra: string; limites: string; dono: string; acao?: string }

