  'receita.tr': { mede: 'Onde está o saldo vencido: decomposição por regional, porte, atraso, atividade e RT.', calcula: 'Árvore de decomposição do saldo vencido em D, uma dimensão por coluna.', fontes: INTERNO, regra: V1, limites: 'Cada ramo soma ao total; a ordem das dimensões muda a leitura.', dono: FIN },
  'receita.or': { mede: 'Orçamento dos programas: planejado contra executado no período.', calcula: 'Soma do planejado e do executado por programa nos meses do período.', fontes: 'Orçamento dos programas (modelo institucional demonstrativo).', regra: V1, limites: DEMO, dono: CONTROLE },

